import { useRef, useState } from 'react'
import { useApp } from '../../context/AppContext'
import { useField, useForm, FieldError, rules } from '../../lib/validation'
import './LoginPage.css'

const LOGIN_FOOD_PHOTO = 'data:image/jpeg;base64,'

export default function LoginPage() {
  const { signIn, navigate, notify, setDialog } = useApp()
  const [loading, setLoading] = useState(false)
  const [shake, setShake] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const submitRef = useRef(null)

  // ── Live-validated fields ─────────────────────────────────────
  const identifier = useField('', (v) => {
    if (!v.trim()) return 'Email or username is required.'
    if (v.length > 254) return 'Too long — max 254 characters.'
    const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())
    const validUsername = /^[a-z0-9._-]{3,40}$/i.test(v.trim())
    if (!validEmail && !validUsername) {
      return 'Enter a valid email (you@example.com) or username (3–40 chars).'
    }
    return null
  })

  const password = useField('', rules.passwordLogin)
  const form = useForm({ identifier, password })

  async function submit(e) {
    e.preventDefault()
    form.touchAll()

    if (!form.isValid) {
      setShake(true)
      setTimeout(() => setShake(false), 400)
      return
    }

    setLoading(true)
    try {
      const result = await signIn(identifier.value.trim().toLowerCase(), password.value)
      const role = result?.account?.role || 'account'
      notify(`Welcome back! Signed in as ${role}.`, {
        icon: 'success',
        title: 'Signed in',
        timer: 2000,
      })
    } catch (err) {
      notify(err.message || 'Sign-in failed. Check your credentials and try again.', {
        icon: 'error',
        title: 'Sign-in failed',
        timer: 4000,
      })
    } finally {
      setLoading(false)
    }
  }

  return (
    <main className="rmj-login-page">
      {/* Subtle botanical leaf decorations on the outer right corners */}
      <svg
        className="rmj-lgn-page-leaf rmj-lgn-page-leaf-tr"
        viewBox="0 0 220 180"
        fill="none"
        aria-hidden="true"
      >
        <path d="M220 -10 C150 8 92 46 58 104 C118 102 176 62 220 -10 Z" fill="#63A432" />
        <path
          d="M215 -6 Q135 46 62 100"
          stroke="#B9E04C"
          strokeWidth="2.2"
          strokeLinecap="round"
        />
        <path d="M230 30 C178 62 142 108 128 164 C178 138 214 92 230 30 Z" fill="#7AB840" />
        <path
          d="M224 34 Q174 96 132 160"
          stroke="#D4E157"
          strokeWidth="2"
          strokeLinecap="round"
        />
      </svg>

      <svg
        className="rmj-lgn-page-leaf rmj-lgn-page-leaf-br"
        viewBox="0 0 230 190"
        fill="none"
        aria-hidden="true"
      >
        <path d="M230 190 C212 120 176 60 122 18 C122 80 158 142 230 190 Z" fill="#54962A" />
        <path
          d="M224 185 Q172 104 126 22"
          stroke="#B2DB44"
          strokeWidth="2.2"
          strokeLinecap="round"
        />
        <path d="M200 196 C162 140 108 104 46 92 C78 146 128 182 200 196 Z" fill="#70B23A" />
        <path
          d="M196 192 Q122 142 50 94"
          stroke="#CBE85E"
          strokeWidth="2"
          strokeLinecap="round"
        />
      </svg>

      {/* Split-Screen Two-Column Container */}
      <div className="rmj-login-split">
        {/* ══════════════ LEFT SECTION: BRANDING PANEL ══════════════ */}
        <section className="rmj-login-brand-panel" aria-label="RMJohns Eatery branding">
          <div className="rmj-brand-ambient-glow" aria-hidden="true" />

          {/* Botanical leaf accents inside branding panel */}
          <svg
            className="rmj-panel-leaf rmj-panel-leaf-tl"
            viewBox="0 0 160 150"
            fill="none"
            aria-hidden="true"
          >
            <path d="M-10 -10 C56 8 108 42 140 96 C82 96 28 58 -10 -10 Z" fill="#5D9E31" />
            <path
              d="M-6 -6 Q68 42 136 92"
              stroke="#B7E048"
              strokeWidth="2.2"
              strokeLinecap="round"
            />
            <path d="M-12 32 C34 62 66 102 78 146 C32 124 -2 82 -12 32 Z" fill="#468223" />
          </svg>

          <svg
            className="rmj-panel-leaf rmj-panel-leaf-bl"
            viewBox="0 0 130 140"
            fill="none"
            aria-hidden="true"
          >
            <path d="M-8 128 C12 72 48 28 96 4 C92 60 56 106 -8 128 Z" fill="#56982B" />
            <path
              d="M-4 124 Q46 64 92 8"
              stroke="#B4DC44"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>

          <svg
            className="rmj-panel-leaf rmj-panel-leaf-mr"
            viewBox="0 0 110 120"
            fill="none"
            aria-hidden="true"
          >
            <path d="M112 10 C68 28 36 64 20 110 C66 104 98 68 112 10 Z" fill="#68AD35" />
            <path
              d="M108 14 Q64 62 24 106"
              stroke="#C5E655"
              strokeWidth="1.8"
              strokeLinecap="round"
            />
          </svg>

          {/* Bottom-left flowing lime wave inside branding panel */}
          <svg
            className="rmj-panel-bottom-wave"
            viewBox="0 0 320 100"
            preserveAspectRatio="none"
            fill="none"
            aria-hidden="true"
          >
            <path d="M0 18 C110 28 210 64 320 100 L0 100 Z" fill="#B8DC48" />
            <path d="M0 44 C95 54 185 76 270 100 L0 100 Z" fill="#CBE668" fillOpacity="0.65" />
          </svg>

          {/* Top & Middle Branding Copy */}
          <div className="rmj-brand-content">
            <a
              href="/"
              className="rmj-brand-logo-link"
              aria-label="Return to Rmjohns Landing Page"
              onClick={(e) => {
                e.preventDefault()
                navigate('Landing')
              }}
            >
              <div className="rmj-brand-logo-frame">
                <img
                  src="/rmjohns-logo.jpg"
                  alt="RMJohns Eatery official logo"
                  className="rmj-brand-logo-img"
                />
              </div>

              <div className="rmj-brand-title-block">
                <strong className="rmj-brand-title-main">RMJohn&apos;s</strong>
                <div className="rmj-brand-subtitle-row">
                  <span className="rmj-brand-subtitle-line" aria-hidden="true" />
                  <span className="rmj-brand-subtitle-text">EATERY</span>
                  <span className="rmj-brand-subtitle-line" aria-hidden="true" />
                </div>
              </div>
            </a>

            <div className="rmj-brand-headline-block">
              <h1 className="rmj-brand-headline">
                Good Food.
                <span className="rmj-brand-headline-accent">Great Service.</span>
              </h1>
              <svg
                className="rmj-brand-swish"
                viewBox="0 0 200 12"
                fill="none"
                aria-hidden="true"
              >
                <path
                  d="M4 9 Q100 2 196 8"
                  stroke="#B8DC48"
                  strokeWidth="3.5"
                  strokeLinecap="round"
                />
              </svg>
            </div>

            <div className="rmj-brand-support-row">
              <span className="rmj-support-icon-circle" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M7 2v9a2 2 0 0 1-2 2v9H3v-9a2 2 0 0 1-2-2V2h2v7h1V2h2v7h1V2h2Zm10 0c2.21 0 4 2.24 4 5 0 2.25-1.2 4.15-2.85 4.78L18 22h-2.5l-.15-10.22C13.7 11.15 12.5 9.25 12.5 7c0-2.76 1.79-5 4-5Z" />
                </svg>
              </span>
              <p className="rmj-brand-support-text">
                Your restaurant management
                <br />
                starts here.
              </p>
            </div>
          </div>

          {/* Bottom High-Resolution Food Photography */}
          <div className="rmj-brand-food-wrap">
            <div className="rmj-brand-food-frame">
              <img
                src={LOGIN_FOOD_PHOTO}
                alt="Freshly plated Filipino grilled pork meal with garlic rice and vegetables"
                className="rmj-brand-food-img"
              />
            </div>
          </div>
        </section>

        {/* ══════════════ RIGHT SECTION: LOGIN FORM CARD ══════════════ */}
        <div className="rmj-login-card-wrap">
          <form
            ref={submitRef}
            className={`rmj-login-card${shake ? ' v-shake' : ''}`}
            onSubmit={submit}
            noValidate
          >
            {/* Elegant restaurant cloche icon */}
            <div className="rmj-login-cloche-icon" aria-hidden="true">
              <svg viewBox="0 0 88 60" fill="none">
                <line x1="8" y1="26" x2="18" y2="26" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" />
                <line x1="4" y1="34" x2="15" y2="34" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" />
                <line x1="10" y1="42" x2="18" y2="42" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" />
                <path
                  d="M52 14a4 4 0 1 0-8 0"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinecap="round"
                />
                <path
                  d="M24 40c0-13.25 10.75-24 24-24s24 10.75 24 24H24Z"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinejoin="round"
                />
                <rect
                  x="20"
                  y="40"
                  width="56"
                  height="6"
                  rx="3"
                  stroke="currentColor"
                  strokeWidth="3"
                />
                <path
                  d="M28 46l3 5h34l3-5"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </div>

            <h2 className="rmj-login-heading">Sign in to Your Account</h2>
            <p className="rmj-login-subtitle">Admin &amp; Staff Management Portal</p>
            <div style={{
              fontSize: '0.8rem',
              color: '#468223',
              background: '#EAF5E9',
              padding: '6px 12px',
              borderRadius: '8px',
              marginBottom: '16px',
              textAlign: 'center',
              fontWeight: '500'
            }}>
              📱 Customers: Please use the RMJohn&apos;s Mobile App to order.
            </div>

            <div className="rmj-login-field-group">
              {/* Email or Username Field */}
              <div className="rmj-login-field-wrap">
                <div
                  className={`rmj-login-input-box${
                    identifier.touched && identifier.error ? ' has-error' : ''
                  }`}
                >
                  <span className="rmj-input-left-icon" aria-hidden="true">
                    <svg
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <rect x="3" y="5" width="18" height="14" rx="2.5" />
                      <polyline points="3 7 12 13 21 7" />
                    </svg>
                  </span>
                  <input
                    type="text"
                    name="identifier"
                    autoComplete="username"
                    maxLength={254}
                    placeholder="Email or username"
                    aria-label="Email or username"
                    required
                    disabled={loading}
                    value={identifier.value}
                    onChange={identifier.onChange}
                    onBlur={identifier.onBlur}
                    className="rmj-login-input"
                  />
                </div>
                <FieldError field={identifier} label="Email or username" />
              </div>

              {/* Password Field with Show/Hide Toggle */}
              <div className="rmj-login-field-wrap">
                <div
                  className={`rmj-login-input-box${
                    password.touched && password.error ? ' has-error' : ''
                  }`}
                >
                  <span className="rmj-input-left-icon" aria-hidden="true">
                    <svg
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <rect x="4" y="11" width="16" height="10" rx="2.5" />
                      <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                      <circle cx="12" cy="16" r="1.2" fill="currentColor" stroke="none" />
                    </svg>
                  </span>
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="password"
                    autoComplete="current-password"
                    maxLength={64}
                    placeholder="Password"
                    aria-label="Password"
                    required
                    disabled={loading}
                    value={password.value}
                    onChange={password.onChange}
                    onBlur={password.onBlur}
                    className="rmj-login-input"
                  />
                  <button
                    type="button"
                    className="rmj-pw-toggle-btn"
                    onClick={() => setShowPassword((prev) => !prev)}
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                    title={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? (
                      <svg
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8Z" />
                        <circle cx="12" cy="12" r="3" />
                      </svg>
                    ) : (
                      <svg
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
                        <line x1="1" y1="1" x2="23" y2="23" />
                      </svg>
                    )}
                  </button>
                </div>
                <FieldError field={password} label="Password" />
              </div>
            </div>

            {/* Forgot Password Link */}
            <div className="rmj-forgot-row">
              <button
                type="button"
                className="rmj-forgot-btn"
                disabled={loading}
                onClick={() => setDialog({ type: 'account', mode: 'forgot' })}
              >
                Forgot password?
              </button>
            </div>

            {/* Large Forest-Green Sign In Button */}
            <button type="submit" className="rmj-signin-btn" disabled={loading}>
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4" />
                <polyline points="10 17 15 12 10 7" />
                <line x1="15" y1="12" x2="3" y2="12" />
              </svg>
              <span>{loading ? 'Signing in\u2026' : 'Sign In'}</span>
            </button>

            <div className="rmj-login-divider">
              <span>or continue with</span>
            </div>

            <div className="rmj-register-prompt">
              <span>Don&apos;t have an account?</span>
              <button
                type="button"
                className="rmj-register-link-btn"
                disabled={loading}
                onClick={() => setDialog({ type: 'account', mode: 'register' })}
              >
                Sign up
              </button>
            </div>

            {/* Security Message */}
            <p className="rmj-security-note">
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" />
                <rect x="9.5" y="11" width="5" height="4" rx="1" />
                <path d="M10.5 11V9.5a1.5 1.5 0 0 1 3 0V11" />
              </svg>
              <span>Your account is secure and protected.</span>
            </p>
          </form>
        </div>
      </div>
    </main>
  )
}
